WITH expected AS (SELECT row_number() OVER (ORDER BY a) AS pos,a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a LIMIT 1000), got AS (SELECT result.*,row_number() OVER (PARTITION BY run ORDER BY result.rowid) AS pos FROM result) SELECT count(*) AS stored_rows,(SELECT count(*) FROM (SELECT run FROM result GROUP BY run HAVING run BETWEEN 1 AND 10 AND count(*)=1000)) AS complete_runs,coalesce(sum((got.run NOT BETWEEN 1 AND 10) OR expected.pos IS NULL OR got.a IS NOT expected.a OR got.c0 IS NOT expected.c0 OR got.c2 IS NOT expected.c2 OR got.c3 IS NOT expected.c3 OR got.c4 IS NOT expected.c4 OR got.c5 IS NOT expected.c5 OR got.c6 IS NOT expected.c6 OR got.b IS NOT expected.b),0) AS bad_rows FROM got LEFT JOIN expected ON expected.pos=got.pos;